'use strict'
const Fastify = require('./fastify.js')

function race (p) {
  return Promise.race([
    p.then(v => 'resolved: ' + v, e => 'rejected: ' + (e && e.message)),
    new Promise(res => setTimeout(() => res('PENDING'), 500))
  ])
}

async function main () {
  // 1. already aborted
  {
    const controller = new AbortController()
    controller.abort(new Error('aborting before actual start'))
    const fastify = Fastify()
    console.log('already aborted ->', await race(fastify.listen({ port: 1234, signal: controller.signal })), '| listening:', fastify.server.listening)
  }

  // 2. aborted right after listen() is called (while getting ready)
  {
    const controller = new AbortController()
    const fastify = Fastify()
    fastify.register(async () => { await new Promise(r => setTimeout(r, 50)) })
    const p = race(fastify.listen({ port: 1234, signal: controller.signal }))
    controller.abort(new Error('aborted while readying'))
    console.log('abort during ready ->', await p, '| listening:', fastify.server.listening)
  }

  // 3. aborted synchronously after ready, in the same tick as server.listen
  {
    const controller = new AbortController()
    const fastify = Fastify()
    const p = race(fastify.listen({ port: 1234, signal: controller.signal }))
    setTimeout(() => controller.abort(), 10)
    console.log('abort default reason ->', await p, '| listening:', fastify.server.listening)
  }

  // 4. normal listen still works, abort after listening closes the server
  {
    const controller = new AbortController()
    const fastify = Fastify()
    console.log('normal ->', await race(fastify.listen({ port: 0, signal: controller.signal })))
    controller.abort()
    await new Promise(r => setTimeout(r, 100))
    console.log('after abort listening:', fastify.server.listening)
  }

  process.exit(0)
}

main()

